"use client";

import { useRef } from "react";
import { useBloomCanvas } from "../hooks/useBloomCanvas";
import { usePointerInk } from "../hooks/usePointerInk";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import type { ScrollProgress } from "../hooks/useScrollProgress";

type BloomCanvasProps = {
  /** Optional scroll-progress ref; when supplied, petals accumulate with scroll. */
  progress?: React.RefObject<ScrollProgress>;
  /** Accessible bilingual description of the scene. */
  ariaLabel: string;
  className?: string;
};

/**
 * The ink-bloom canvas: a DPR-aware stage where ink drops fall, strike the
 * waterline, and bloom into drifting petals. This thin wrapper owns the three
 * refs the physics needs (stage, canvas, pointer) and hands them to
 * useBloomCanvas; all the simulation lives in the hook.
 *
 * The stage is role="img" with a bilingual description (EN + JA), and the
 * canvas itself is aria-hidden — the meaning is conveyed by the label, the
 * motion by the pixels.
 */
export default function BloomCanvas({
  progress,
  ariaLabel,
  className,
}: BloomCanvasProps) {
  const stageRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const { pointer, drops } = usePointerInk(stageRef);

  useBloomCanvas(stageRef, canvasRef, reduced, { pointer, drops, progress });

  return (
    <div
      ref={stageRef}
      className={className ?? "sakura-bloom"}
      role="img"
      aria-label={ariaLabel}
    >
      <canvas ref={canvasRef} className="sakura-bloom__canvas" aria-hidden="true" />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/** The bloom seal holds this long before the night lifts (ms). */
const HOLD_MS = 1400;
/** How long the lift itself takes — must match --sakura-loader-lift in CSS. */
const LIFT_MS = 650;

/**
 * The entry: a beat of blank ink-night, a gold bloom seal (桜) pressed into
 * it, then the night lifts and the garden is already blooming underneath.
 * It exists to buy the bloom canvas its first breath — nothing more — so it
 * is aggressively skippable: any key, tap, wheel, or scroll lifts it at
 * once, a hard timeout lifts it regardless, and under reduced motion (or
 * with JavaScript off) it never appears at all. `onDone` fires when the lift
 * *starts*, so the hero's glyph cadence overlaps the night leaving.
 */
export default function Loader({ onDone }: { onDone: () => void }) {
  const reduced = usePrefersReducedMotion();
  const [phase, setPhase] = useState<"idle" | "held" | "lifting" | "gone">(
    "idle",
  );

  useEffect(() => {
    if (reduced) {
      const id = window.setTimeout(() => {
        setPhase("gone");
        onDone();
      }, 0);
      return () => window.clearTimeout(id);
    }

    let lifted = false;
    let liftTimer = 0;
    const lift = () => {
      if (lifted) return;
      lifted = true;
      setPhase("lifting");
      onDone();
      liftTimer = window.setTimeout(() => setPhase("gone"), LIFT_MS);
    };

    const showTimer = window.setTimeout(() => {
      setPhase((p) => (p === "idle" ? "held" : p));
    }, 10);
    const holdTimer = window.setTimeout(lift, HOLD_MS);
    const opts = { passive: true } as const;
    window.addEventListener("keydown", lift);
    window.addEventListener("pointerdown", lift, opts);
    window.addEventListener("wheel", lift, opts);
    window.addEventListener("touchstart", lift, opts);
    window.addEventListener("scroll", lift, opts);

    return () => {
      window.clearTimeout(showTimer);
      window.clearTimeout(holdTimer);
      window.clearTimeout(liftTimer);
      window.removeEventListener("keydown", lift);
      window.removeEventListener("pointerdown", lift);
      window.removeEventListener("wheel", lift);
      window.removeEventListener("touchstart", lift);
      window.removeEventListener("scroll", lift);
    };
  }, [reduced, onDone]);

  if (phase === "idle" || phase === "gone") return null;

  return (
    <div
      className={`sakura-loader ${phase === "lifting" ? "is-lifting" : ""}`}
      aria-hidden="true"
    >
      <div className="sakura-loader__seal">
        <svg viewBox="0 0 96 96" width={96} height={96} focusable="false">
          <rect
            x="6"
            y="6"
            width="84"
            height="84"
            rx="4"
            fill="#c9a85a"
          />
          <rect
            x="12.5"
            y="12.5"
            width="71"
            height="71"
            rx="2"
            fill="none"
            stroke="#0e0a0f"
            strokeOpacity="0.4"
            strokeWidth="1"
          />
          <text
            className="sakura-sealglyph"
            x="48"
            y="66"
            textAnchor="middle"
            fontSize="46"
            fill="#0e0a0f"
          >
            桜
          </text>
        </svg>
        <p className="sakura-loader__word">
          <span lang="ko">잉크와 개화</span>{" "}
          <span lang="ja">墨と花咲</span>
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import BloomCanvas from "./BloomCanvas";
import { useScrollProgress } from "../hooks/useScrollProgress";

/** The four verses of mono no aware — the gentle sorrow of transient beauty.
 *  Each is Korean (main voice) + Japanese (source) + English (subtitle).
 *  Order: arrival → bloom → fall → memory. */
const VERSES: {
  ko: string[];
  ja: string[];
  en: string;
  num: string;
}[] = [
  {
    num: "一",
    ko: ["먹방울 하나,", "밤하늘에서 떨어진다."],
    ja: ["墨のしずくひとつ、", "夜の空から落ちる。"],
    en: "One drop of ink, falling through the night.",
  },
  {
    num: "二",
    ko: ["물에 닿아,", "꽃으로 피어난다."],
    ja: ["水に触れ、", "花として咲く。"],
    en: "It meets the water, and blooms into a flower.",
  },
  {
    num: "三",
    ko: ["바람에 흩날려,", "천천히 진다."],
    ja: ["風に散り、", "ゆっくりと朽ちる。"],
    en: "It scatters on the wind, and slowly fades.",
  },
  {
    num: "四",
    ko: ["사라진 자리에,", "기억만 남는다."],
    ja: ["消えたあとに、", "記憶だけが残る。"],
    en: "Where it was, only the memory remains.",
  },
];

/** Map scroll progress (0..1) onto a verse index. Each verse owns a 0.25-wide
 *  window. */
function verseForProgress(p: number): number {
  return Math.min(VERSES.length - 1, Math.floor(p * VERSES.length));
}

/**
 * Section 02 — the pinned verses. A tall section (≈2.5 viewports) whose
 * inner stage is position: sticky for the scroll length; as progress runs
 * 0→1, the bloom canvas accumulates petals (density floor rises with
 * progress) and the four verses crossfade in sequence. Scrubbing back clears
 * them — petals are not permanent, which is the whole point of mono no aware.
 *
 * The verse marker (一二三四) sets vertically in Shippori Mincho; the Korean
 * body in Noto Serif KR is the voice that speaks; the Japanese source sits
 * beside it; the English subtitle is the quiet translation beneath. Reduced
 * motion: the first verse is shown statically, the canvas paints one composed
 * bloom — the page is a finished garden, not a paused video.
 */
export default function VerseScrub() {
  const { ref, progress } = useScrollProgress<HTMLDivElement>();

  return (
    <section
      className="sakura-verses"
      aria-labelledby="sakura-verses-title"
      ref={ref}
      style={
        { "--sakura-verse-count": VERSES.length } as CSSProperties
      }
    >
      {/* The sticky stage holds for the whole scroll length. */}
      <div className="sakura-verses__pin">
        <div className="sakura-verses__sechead" data-reveal="">
          <p className="sakura-eyebrow" aria-hidden="true">
            <span lang="ko">02 — 것의 아와레</span>{" "}
            <span lang="ja">もののあわれ</span>
          </p>
          <h2 className="sakura-verses__title" id="sakura-verses-title">
            <span lang="ko">넉 편의 시</span>{" "}
            <span lang="ja" className="sakura-verses__titleja">
              四つの句
            </span>
          </h2>
        </div>

        {/* The bloom canvas in this section reads the progress ref, so
            petals accumulate as you read and clear as you leave. */}
        <BloomCanvas
          className="sakura-verses__bloom"
          progress={progress}
          ariaLabel="스크롤에 따라 벚꽃잎이 쌓이고 지워지는 장면. Petals accumulate as you scroll through the verses, and clear as you leave."
        />

        <VerseStack progress={progress} />

        <p className="sakura-verses__caption" data-reveal>
          <span lang="ko">
            스크롤을 천천히 움직여 보세요. 꽃잎이 당신의 읽기에 맞춰 피고
            집니다.
          </span>{" "}
          <span lang="en">
            Scroll slowly. The petals bloom and clear to the pace of your
            reading — nothing here is meant to stay.
          </span>
        </p>
      </div>
    </section>
  );
}

/**
 * Renders all four verses stacked absolutely; a rAF loop writes
 * --sakura-verse-p (smoothed 0..1) onto the stack so CSS crossfades the
 * active verse. Each verse carries its index as data-i; CSS shows the one
 * whose 0.25-wide window contains p, with a soft crossfade at the edges.
 * The loop also manages aria-hidden so only the active verse is read by AT.
 */
function VerseStack({
  progress,
}: {
  progress: React.RefObject<{ p: number; raw: number; t: number }>;
}) {
  const stackRef = useRef<HTMLDivElement | null>(null);
  const smoothed = useRef(0);

  useEffect(() => {
    let raf = 0;
    let last = 0;
    const FRAME_MS = 15.5;
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (now - last < FRAME_MS) return;
      const dt = Math.min(now - last, 48) / 1000;
      last = now;
      const raw = progress.current?.raw ?? 0;
      // lerp smoothed toward raw, frame-rate normalized
      smoothed.current += (raw - smoothed.current) * (1 - Math.exp(-dt * 8));
      const stack = stackRef.current;
      if (!stack) return;
      stack.style.setProperty("--sakura-verse-p", String(smoothed.current));
      const active = verseForProgress(smoothed.current);
      // data-active drives the CSS that crossfades verses; set once per change.
      if (stack.getAttribute("data-active") !== String(active)) {
        stack.setAttribute("data-active", String(active));
        const verses = stack.querySelectorAll<HTMLElement>(".sakura-verse");
        verses.forEach((el, i) => {
          if (i === active) el.removeAttribute("aria-hidden");
          else el.setAttribute("aria-hidden", "true");
        });
      }
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [progress]);

  return (
    <div className="sakura-verses__stack" ref={stackRef}>
      {VERSES.map((v, i) => (
        <article
          key={v.num}
          className="sakura-verse"
          data-i={i}
          aria-hidden={i === 0 ? undefined : "true"}
        >
          <span className="sakura-verse__num" lang="ja" aria-hidden="true">
            {v.num}
          </span>
          <div className="sakura-verse__body">
            <p className="sakura-verse__ko" lang="ko">
              {v.ko.map((line, k) => (
                <span
                  key={k}
                  className="sakura-verse__line"
                  style={
                    { "--kd": `${200 + k * 540}ms` } as CSSProperties
                  }
                >
                  {line}
                </span>
              ))}
            </p>
            <p className="sakura-verse__ja" lang="ja">
              {v.ja.map((line, k) => (
                <span key={k} className="sakura-verse__jline">
                  {line}
                </span>
              ))}
            </p>
            <p className="sakura-verse__en" lang="en">
              {v.en}
            </p>
          </div>
        </article>
      ))}
    </div>
  );
}

"use client";

import { useEffect } from "react";
import type { PointerInkSample, InkDropRequest } from "./usePointerInk";
import type { ScrollProgress } from "./useScrollProgress";

/* -- rendering ------------------------------------------------------------ */
/** Backing-store resolution cap. */
const MAX_DPR = 2;
/** Skip frames that arrive faster than ~64fps (high-refresh displays). */
const FRAME_MS = 15.5;
/** Petal budget: one per this many CSS px² of stage, clamped. */
const AREA_PER_PETAL = 2600;
const MIN_PETALS = 120;
const MAX_PETALS = 520;
/** Maximum simultaneous falling ink drops (older drops are dropped). */
const MAX_DROPS = 14;
/** Maximum simultaneous splash micro-droplets. */
const MAX_SPLASH = 80;

/* -- the curl wind field -------------------------------------------------- */
/** Feature sizes of the two potential octaves (px⁻¹): broad gusts, fine curls. */
const GUST_LARGE = 1 / 170;
const GUST_SMALL = 1 / 64;
/** The noise field itself drifts (px/s): leftward + upward, so gusts travel. */
const FIELD_DRIFT_X = -10;
const FIELD_DRIFT_Y = -14;
/** Curl gain — converts potential slope into px/s of swirl. */
const SWIRL = 720;
/** Finite-difference epsilon for the curl (px). */
const CURL_EPS = 2.5;

/* -- ink drop physics ----------------------------------------------------- */
/** Drop acceleration (px/s²). */
const DROP_GRAVITY = 580;
/** Terminal fall velocity (px/s). */
const DROP_TERMINAL = 480;
/** Drops spawn across the top at this interval when autonomous (s). */
const AUTO_DROP_INTERVAL = 2.6;

/* -- petal physics -------------------------------------------------------- */
/** Petal buoyancy (px/s) — negative: petals sink gently, like real blossoms. */
const PETAL_SINK = -22;
/** Velocity relaxation rate (s⁻¹) — petals have inertia, not obedience. */
const PETAL_RELAX = 1.8;
/** Seconds of life: min + random spread. */
const LIFE_MIN = 7;
const LIFE_SPREAD = 6;
/** Base petal size (px) and growth over life. */
const SIZE_MIN = 7;
const SIZE_SPREAD = 9;
/** Petal rotation (rad/s). */
const ROT_MIN = 0.6;
const ROT_SPREAD = 1.8;

/* -- the bloom burst ------------------------------------------------------ */
/** Petals spawned per drop bloom. */
const BLOOM_MIN = 8;
const BLOOM_SPREAD = 6;
/** Outward velocity of the burst (px/s). */
const BURST_VEL_MIN = 40;
const BURST_VEL_SPREAD = 50;
/** Splash micro-droplets per drop. */
const SPLASH_MIN = 4;
const SPLASH_SPREAD = 3;

/* -- outside influences --------------------------------------------------- */
/** Pointer horizontal pull (px/s per px of distance), capped. */
const POINTER_WIND = 1.3;
const POINTER_CAP = 70;
/** Pointer energy lerps — quick to notice a hand, slow to forget. */
const POINTER_ATTACK = 0.06;
const POINTER_RELEASE = 0.02;
/** Autonomous breeze: two slow sines with unrelated periods. */
function breezeAt(t: number): number {
  return 18 * Math.sin(t * 0.19) + 9 * Math.sin(t * 0.43 + 1.4);
}

/* -- warmup --------------------------------------------------------------- */
/** Pre-advect the petal field so the garden is already blooming on first paint. */
const WARMUP_STEPS = 90;
const WARMUP_DT = 0.09;

/** Layout of a petal in the Float32Array: x, y, vx, vy, age, life, size, rot, vrot, tone. */
const PSTRIDE = 10;

function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

/** Deterministic PRNG — the garden blooms the same way every visit. */
function mulberry32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let z = Math.imul(s ^ (s >>> 15), 1 | s);
    z = (z + Math.imul(z ^ (z >>> 7), 61 | z)) ^ z;
    return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
  };
}

/** 256-entry permutation for the lattice hash. Seeded 718 — the bloom date. */
function buildPerm(): Uint8Array {
  const rand = mulberry32(20260718);
  const p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  for (let i = 255; i > 0; i--) {
    const j = (rand() * (i + 1)) | 0;
    const t = p[i];
    p[i] = p[j];
    p[j] = t;
  }
  return p;
}

const PERM = buildPerm();

/** Lattice hash → [0, 1). */
function latHash(ix: number, iy: number): number {
  return PERM[(ix + PERM[iy & 255]) & 255] / 255;
}

/** Smooth-stepped bilinear value noise over the integer lattice. */
function valueNoise(x: number, y: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  let fx = x - ix;
  let fy = y - iy;
  fx = fx * fx * (3 - 2 * fx);
  fy = fy * fy * (3 - 2 * fy);
  const a = latHash(ix, iy);
  const b = latHash(ix + 1, iy);
  const c = latHash(ix, iy + 1);
  const d = latHash(ix + 1, iy + 1);
  return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
}

/**
 * The scalar potential ψ for the wind. Two octaves of value noise; the whole
 * field drifts leftward + upward over time so gusts travel with the petals
 * instead of petals swimming through frozen wind. (Echoes KEMURI's smoke
 * field-rise, but in 2D and downward-left, the way spring weather moves.)
 */
function psi(x: number, y: number, t: number): number {
  const xr = x + t * FIELD_DRIFT_X;
  const yr = y + t * FIELD_DRIFT_Y;
  return (
    valueNoise(xr * GUST_LARGE, yr * GUST_LARGE) -
    0.5 +
    (valueNoise(xr * GUST_SMALL + 23.1, yr * (GUST_SMALL * 1.3) + 7.7) - 0.5) *
      0.4
  );
}

/**
 * A single cherry-petal sprite: a 5-pointed notched blossom, prerendered to a
 * small offscreen canvas so each particle is one drawImage (no per-frame path
 * building). Three tones for variety: fresh bloom, mid blossom, pale edge.
 * Built from the sheet's blossom tokens.
 */
function makePetalSprite(
  fill: string,
  notch: string,
): HTMLCanvasElement {
  const size = 48;
  const c = document.createElement("canvas");
  c.width = size;
  c.height = size;
  const cx = c.getContext("2d");
  if (cx) {
    cx.translate(size / 2, size / 2);
    // A 5-petal cherry blossom: five notched lobes around a center, drawn as
    // a single filled path. The notch at each tip is what makes it read as
    // sakura rather than a generic flower.
    const R = size * 0.42;
    const r = R * 0.42;
    cx.beginPath();
    for (let i = 0; i < 5; i++) {
      const a0 = (i / 5) * Math.PI * 2 - Math.PI / 2;
      const a1 = ((i + 0.5) / 5) * Math.PI * 2 - Math.PI / 2;
      const a2 = ((i + 1) / 5) * Math.PI * 2 - Math.PI / 2;
      // outer point with a small notch (two close points) at the petal tip
      const tipX = Math.cos(a1) * R;
      const tipY = Math.sin(a1) * R;
      const notchA = a1 - 0.12;
      const notchB = a1 + 0.12;
      if (i === 0) cx.moveTo(Math.cos(a0) * r, Math.sin(a0) * r);
      cx.quadraticCurveTo(
        Math.cos(a0 + 0.25) * R * 0.9,
        Math.sin(a0 + 0.25) * R * 0.9,
        Math.cos(notchA) * R * 0.96,
        Math.sin(notchA) * R * 0.96,
      );
      cx.lineTo(tipX * 0.78, tipY * 0.78); // notch valley
      cx.lineTo(Math.cos(notchB) * R * 0.96, Math.sin(notchB) * R * 0.96);
      cx.quadraticCurveTo(
        Math.cos(a2 - 0.25) * R * 0.9,
        Math.sin(a2 - 0.25) * R * 0.9,
        Math.cos(a2) * r,
        Math.sin(a2) * r,
      );
    }
    cx.closePath();
    cx.fillStyle = fill;
    cx.fill();
    // a soft inner highlight toward the center, in the notch tone
    const grad = cx.createRadialGradient(0, 0, 0, 0, 0, R * 0.5);
    grad.addColorStop(0, notch);
    grad.addColorStop(1, "rgba(0,0,0,0)");
    cx.fillStyle = grad;
    cx.fill();
  }
  return c;
}

/** A soft radial ink sprite: the falling drop and the splash droplets. */
function makeInkSprite(r: number, g: number, b: number, core: number): HTMLCanvasElement {
  const size = 32;
  const c = document.createElement("canvas");
  c.width = size;
  c.height = size;
  const cx = c.getContext("2d");
  if (cx) {
    const grad = cx.createRadialGradient(16, 16, 0, 16, 16, 16);
    grad.addColorStop(0, `rgba(${r},${g},${b},${core})`);
    grad.addColorStop(0.5, `rgba(${r},${g},${b},${core * 0.5})`);
    grad.addColorStop(1, `rgba(${r},${g},${b},0)`);
    cx.fillStyle = grad;
    cx.fillRect(0, 0, size, size);
  }
  return c;
}

/** A gold dust mote: the one warm grain, prerendered. */
function makeGoldSprite(): HTMLCanvasElement {
  const size = 16;
  const c = document.createElement("canvas");
  c.width = size;
  c.height = size;
  const cx = c.getContext("2d");
  if (cx) {
    const grad = cx.createRadialGradient(8, 8, 0, 8, 8, 8);
    grad.addColorStop(0, "rgba(201,168,90,0.9)");
    grad.addColorStop(0.4, "rgba(201,168,90,0.4)");
    grad.addColorStop(1, "rgba(201,168,90,0)");
    cx.fillStyle = grad;
    cx.fillRect(0, 0, size, size);
  }
  return c;
}

export type BloomCanvasOptions = {
  /** Refs from usePointerInk — wind bias + click-to-drop queue. */
  pointer: React.RefObject<PointerInkSample>;
  drops: React.RefObject<InkDropRequest[]>;
  /** Optional scroll-progress ref (verse section). When present and >0, the
   *  garden spawns extra ink-drops and holds a petal-density floor, so petals
   *  accumulate as the reader scrubs the verses. */
  progress?: React.RefObject<ScrollProgress>;
};

/**
 * The signature moment. Ink drops fall from the top of the stage (or from a
 * pointer tap), accelerate under gravity, and on striking an invisible
 * waterline (y = 0.42·H) they splash and BLOOM: a ring of 8–14 petal
 * particles spawns outward and is then advected through a divergence-free
 * curl-noise wind field (velocity = (∂ψ/∂y, −∂ψ/∂x)), so petals drift and
 * coil like real blossoms on spring air but never compress or tear. Petals
 * sink gently (negative buoyancy — cherry blossoms fall, they do not rise),
 * relax toward the field at 1.8 s⁻¹ (inertia), and fade over 7–13 s.
 *
 * The wind leans toward a fine pointer (horizontal pull capped ±70 px/s,
 * energy attack .06/release .02); on touch or idle a two-sine breeze
 * (~33 s and ~15 s periods) keeps the garden alive. Ink drops fall
 * autonomously every ~2.6 s so the page is never still even without a hand.
 *
 * If `progress` is supplied, scroll progress 0→1 raises the autonomous drop
 * rate and enforces a petal-density floor — the verse section scrubs petals
 * into being as you read, and lets them clear as you leave.
 *
 * Reduced motion pre-advects the field and paints one composed still: a
 * garden already in mid-bloom, one drop frozen mid-fall, petals resting
 * where the breeze holds them. The loop pauses offscreen and when the tab
 * hides.
 */
export function useBloomCanvas(
  stageRef: React.RefObject<HTMLDivElement | null>,
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  reduced: boolean,
  opts: BloomCanvasOptions,
) {
  useEffect(() => {
    const stage = stageRef.current;
    const canvas = canvasRef.current;
    if (!stage || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const fine = window.matchMedia(
      "(hover: hover) and (pointer: fine)",
    ).matches;
    const rand = mulberry32(718);

    // Sprites — every color a sheet token:
    // blossom #e8869e · bloom #f4c2d4 · petal-white #f6eef0 · gold #c9a85a
    // ink (the drop) uses a near-black with a warm undertone: #0e0a0f's ink.
    const petalFresh = makePetalSprite("rgba(232,134,158,0.92)", "rgba(246,238,240,0.5)");
    const petalMid = makePetalSprite("rgba(244,194,212,0.9)", "rgba(246,238,240,0.55)");
    const petalPale = makePetalSprite("rgba(246,238,240,0.85)", "rgba(244,194,212,0.4)");
    const inkDrop = makeInkSprite(20, 14, 22, 0.95);
    const inkSplash = makeInkSprite(30, 20, 32, 0.7);
    const gold = makeGoldSprite();
    const petalSprites = [petalFresh, petalMid, petalPale];

    let W = 0;
    let H = 0;
    let waterY = 0;
    let count = 0;
    let parts = new Float32Array(0);

    // Falling drops: x, y, vy, alive flag stored as separate small arrays.
    const drops: { x: number; y: number; vy: number; alive: boolean }[] = [];
    // Splash micro-droplets: x, y, vx, vy, age, life.
    const splashes: { x: number; y: number; vx: number; vy: number; age: number; life: number }[] = [];
    // Gold motes: a handful of slow drifters for warmth.
    const motes: { x: number; y: number; r: number; ph: number; vx: number; vy: number }[] = [];

    let raf = 0;
    let running = false;
    let inView = false;
    let last = 0;
    let t = 0; // simulation clock, seconds
    let autoDropTimer = 0;

    const ptr = { x: 0, y: 0, e: 0 };

    const spawnPetal = (i: number, warm: boolean, atX?: number, atY?: number) => {
      const o = i * PSTRIDE;
      parts[o] = atX ?? rand() * W;
      parts[o + 1] = atY ?? rand() * waterY;
      parts[o + 2] = (rand() - 0.5) * 20;
      parts[o + 3] = PETAL_SINK * (0.7 + rand() * 0.6);
      parts[o + 5] = LIFE_MIN + rand() * LIFE_SPREAD;
      parts[o + 4] = warm ? rand() * parts[o + 5] : 0;
      parts[o + 6] = SIZE_MIN + rand() * SIZE_SPREAD;
      parts[o + 7] = rand() * Math.PI * 2;
      parts[o + 8] = (rand() < 0.5 ? -1 : 1) * (ROT_MIN + rand() * ROT_SPREAD);
      parts[o + 9] = (rand() * 3) | 0; // tone index
    };

    const bloom = (x: number) => {
      // A drop has struck the waterline at x. Splash + spawn a ring of petals.
      const n = BLOOM_MIN + ((rand() * BLOOM_SPREAD) | 0);
      const baseAngle = rand() * Math.PI * 2;
      for (let k = 0; k < n; k++) {
        // find a dead/recyclable petal slot
        let slot = -1;
        for (let i = 0; i < count; i++) {
          const o = i * PSTRIDE;
          if (parts[o + 4] >= parts[o + 5]) {
            slot = i;
            break;
          }
        }
        if (slot < 0) break;
        const o = slot * PSTRIDE;
        const ang =
          baseAngle + (k / n) * Math.PI * 2 + (rand() - 0.5) * 0.8;
        const spd = BURST_VEL_MIN + rand() * BURST_VEL_SPREAD;
        parts[o] = x + (rand() - 0.5) * 8;
        parts[o + 1] = waterY + (rand() - 0.5) * 4;
        parts[o + 2] = Math.cos(ang) * spd;
        parts[o + 3] = Math.sin(ang) * spd * 0.6 + PETAL_SINK;
        parts[o + 5] = LIFE_MIN + rand() * LIFE_SPREAD;
        parts[o + 4] = 0;
        parts[o + 6] = SIZE_MIN + rand() * SIZE_SPREAD;
        parts[o + 7] = rand() * Math.PI * 2;
        parts[o + 8] = (rand() < 0.5 ? -1 : 1) * (ROT_MIN + rand() * ROT_SPREAD);
        parts[o + 9] = (rand() * 3) | 0;
      }
      // micro-droplets splash upward
      const sn = SPLASH_MIN + ((rand() * SPLASH_SPREAD) | 0);
      for (let k = 0; k < sn; k++) {
        if (splashes.length >= MAX_SPLASH) splashes.shift();
        const ang = -Math.PI / 2 + (rand() - 0.5) * 1.8;
        const spd = 60 + rand() * 90;
        splashes.push({
          x: x + (rand() - 0.5) * 10,
          y: waterY,
          vx: Math.cos(ang) * spd,
          vy: Math.sin(ang) * spd,
          age: 0,
          life: 0.4 + rand() * 0.3,
        });
      }
    };

    const releaseDrop = (x: number) => {
      if (drops.length >= MAX_DROPS) drops.shift();
      drops.push({ x, y: 0, vy: 40 + rand() * 30, alive: true });
    };

    const step = (dt: number) => {
      t += dt;
      const relax = 1 - Math.exp(-dt * PETAL_RELAX);
      const breeze = breezeAt(t);

      // --- advance falling drops; on hitting the waterline, bloom ---
      for (const d of drops) {
        if (!d.alive) continue;
        d.vy = Math.min(d.vy + DROP_GRAVITY * dt, DROP_TERMINAL);
        d.y += d.vy * dt;
        if (d.y >= waterY) {
          d.alive = false;
          bloom(d.x);
        }
      }
      // compact dead drops occasionally
      if (drops.length > MAX_DROPS) {
        for (let i = drops.length - 1; i >= 0; i--)
          if (!drops[i].alive) drops.splice(i, 1);
      }

      // --- advance splash micro-droplets (gravity, short life) ---
      for (let i = splashes.length - 1; i >= 0; i--) {
        const s = splashes[i];
        s.vy += 900 * dt;
        s.x += s.vx * dt;
        s.y += s.vy * dt;
        s.age += dt;
        if (s.age >= s.life || s.y > waterY + 8) splashes.splice(i, 1);
      }

      // --- gold motes drift slowly ---
      for (const m of motes) {
        m.x += m.vx * dt;
        m.y += m.vy * dt;
        if (m.x < -20) m.x = W + 20;
        if (m.x > W + 20) m.x = -20;
        if (m.y < -20) m.y = H + 20;
        if (m.y > H + 20) m.y = -20;
      }

      // --- advect petals through the curl wind field ---
      for (let i = 0; i < count; i++) {
        const o = i * PSTRIDE;
        let x = parts[o];
        let y = parts[o + 1];
        const age = parts[o + 4] + dt;
        const life = parts[o + 5];

        if (age >= life || y > H + 40 || x < -60 || x > W + 60) {
          // recycle: respawn drifting in from an edge or mid-air, unless the
          // verse-section density floor is holding us.
          spawnPetal(i, true);
          continue;
        }

        // Divergence-free flow: velocity = (∂ψ/∂y, −∂ψ/∂x).
        const cx =
          (psi(x, y + CURL_EPS, t) - psi(x, y - CURL_EPS, t)) /
          (2 * CURL_EPS);
        const cy =
          -(psi(x + CURL_EPS, y, t) - psi(x - CURL_EPS, y, t)) /
          (2 * CURL_EPS);

        let wind = breeze;
        if (ptr.e > 0.01) {
          const pull = clamp(
            (ptr.x - x) * POINTER_WIND,
            -POINTER_CAP,
            POINTER_CAP,
          );
          const reach = Math.exp(-((y - ptr.y) * (y - ptr.y)) / (H * H * 0.12));
          wind += pull * ptr.e * reach;
        }

        const tvx = cx * SWIRL + wind;
        const tvy = PETAL_SINK + cy * SWIRL * 0.7;

        const vx = parts[o + 2] + (tvx - parts[o + 2]) * relax;
        const vy = parts[o + 3] + (tvy - parts[o + 3]) * relax;
        x += vx * dt;
        y += vy * dt;

        parts[o] = x;
        parts[o + 1] = y;
        parts[o + 2] = vx;
        parts[o + 3] = vy;
        parts[o + 4] = age;
        parts[o + 7] += parts[o + 8] * dt; // rotation
      }
    };

    const draw = () => {
      ctx.clearRect(0, 0, W, H);

      // gold motes — the one warm grain, drawn first (behind petals)
      ctx.globalAlpha = reduced ? 0.5 : 0.42 + 0.12 * Math.sin(t * 0.7);
      for (const m of motes) {
        const r = m.r * (1 + 0.2 * Math.sin(t * 0.9 + m.ph));
        ctx.drawImage(gold, m.x - r, m.y - r, r * 2, r * 2);
      }
      ctx.globalAlpha = 1;

      // petals
      for (let i = 0; i < count; i++) {
        const o = i * PSTRIDE;
        const age = parts[o + 4];
        const life = parts[o + 5];
        const a01 = age / life;
        const x = parts[o];
        const y = parts[o + 1];

        const fadeIn = age > 0.5 ? 1 : age / 0.5;
        const fadeOut = (1 - a01) * Math.sqrt(1 - a01);
        const alpha = 0.8 * fadeIn * fadeOut;
        if (alpha < 0.02) continue;

        const size = parts[o + 6] * (1 + a01 * 0.4);
        const half = size / 2;
        const sprite = petalSprites[parts[o + 9] % 3] ?? petalMid;

        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.translate(x, y);
        ctx.rotate(parts[o + 7]);
        ctx.drawImage(sprite, -half, -half, size, size);
        ctx.restore();
      }
      ctx.globalAlpha = 1;

      // splash micro-droplets (ink, above the waterline)
      for (const s of splashes) {
        const a = (1 - s.age / s.life) * 0.7;
        if (a <= 0) continue;
        ctx.globalAlpha = a;
        ctx.drawImage(inkSplash, s.x - 4, s.y - 4, 8, 8);
      }
      ctx.globalAlpha = 1;

      // falling drops — the ink, descending. Reduced motion freezes one
      // mid-fall for the composed still.
      if (reduced) {
        ctx.globalAlpha = 0.95;
        ctx.drawImage(inkDrop, W * 0.5 - 8, waterY * 0.5 - 8, 16, 20);
        ctx.globalAlpha = 1;
      } else {
        for (const d of drops) {
          if (!d.alive) continue;
          ctx.globalAlpha = 0.95;
          ctx.drawImage(inkDrop, d.x - 5, d.y - 8, 10, 16);
        }
        ctx.globalAlpha = 1;
      }

      // the waterline — a faint shimmer, the only fixed geometry
      const shimmer = reduced ? 0.28 : 0.22 + 0.12 * Math.sin(t * 1.0);
      ctx.globalAlpha = shimmer;
      ctx.strokeStyle = "rgba(168,154,162,0.55)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, waterY + 0.5);
      ctx.lineTo(W, waterY + 0.5);
      ctx.stroke();
      // a soft bloom glow beneath the line
      const glow = ctx.createLinearGradient(0, waterY, 0, waterY + 24);
      glow.addColorStop(0, "rgba(232,134,158,0.12)");
      glow.addColorStop(1, "rgba(232,134,158,0)");
      ctx.fillStyle = glow;
      ctx.fillRect(0, waterY, W, 24);
      ctx.globalAlpha = 1;
    };

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      if (now - last < FRAME_MS) return;
      const dt = Math.min(now - last, 48) / 1000;
      last = now;

      // drain pending ink-drops from pointer taps
      const dropQueue = opts.drops.current;
      while (dropQueue.length > 0) {
        const req = dropQueue.shift()!;
        releaseDrop(clamp(req.x, 8, W - 8));
      }

      // pointer energy: decay toward 0 unless a fresh move arrived
      const ps = opts.pointer.current;
      const sinceMove = (now - ps.t) / 1000;
      if (ps.e > 0.01) {
        ptr.x = ps.x;
        ptr.y = ps.y;
        const idle = sinceMove > 2.6;
        const target = idle ? 0 : ps.e;
        const ek = target > ptr.e ? POINTER_ATTACK : POINTER_RELEASE;
        const k = clamp(dt * 60, 0, 3);
        ptr.e += (target - ptr.e) * ek * k;
      } else {
        ptr.e += (0 - ptr.e) * POINTER_RELEASE * clamp(dt * 60, 0, 3);
      }

      // autonomous drift target when no hand is present
      if (!fine || sinceMove > 2.6) {
        // nothing — breeze handles it; ptr.e decays
      }

      // scroll-progress coupling (verse section): raise drop rate + density floor
      const prog = opts.progress?.current;
      const pRaw = prog ? clamp(prog.raw, 0, 1) : 0;
      autoDropTimer -= dt;
      const dropInterval = AUTO_DROP_INTERVAL / (1 + pRaw * 2.2);
      if (autoDropTimer <= 0) {
        releaseDrop(rand() * W);
        autoDropTimer = dropInterval;
      }
      // density floor: ensure at least progress·count petals are alive
      if (pRaw > 0.05) {
        const floor = Math.round(count * pRaw * 0.7);
        let alive = 0;
        for (let i = 0; i < count; i++) {
          if (parts[i * PSTRIDE + 4] < parts[i * PSTRIDE + 5]) alive++;
        }
        let needed = floor - alive;
        let guard = 0;
        while (needed > 0 && guard < count) {
          const i = guard;
          const o = i * PSTRIDE;
          if (parts[o + 4] >= parts[o + 5]) {
            spawnPetal(i, false);
            needed--;
          }
          guard++;
        }
      }

      step(dt);
      draw();
    };

    const start = () => {
      if (running || reduced) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const warmup = () => {
      for (let i = 0; i < count; i++) spawnPetal(i, true);
      for (let i = 0; i < WARMUP_STEPS; i++) step(WARMUP_DT);
      // a couple of pre-released drops so the waterline shows life
      releaseDrop(W * 0.3);
      releaseDrop(W * 0.7);
    };

    const resize = () => {
      const rect = stage.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) return;
      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      W = rect.width;
      H = rect.height;
      canvas.width = Math.round(W * dpr);
      canvas.height = Math.round(H * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      waterY = H * 0.42;

      const wanted = clamp(
        Math.round((W * H) / AREA_PER_PETAL),
        MIN_PETALS,
        MAX_PETALS,
      );
      if (wanted !== count) {
        count = wanted;
        parts = new Float32Array(count * PSTRIDE);
        warmup();
      }

      // (re)seed gold motes — a handful, scaled to width
      motes.length = 0;
      const moteCount = Math.max(5, Math.round(W / 220));
      const mr = mulberry32(777);
      for (let i = 0; i < moteCount; i++) {
        motes.push({
          x: mr() * W,
          y: mr() * H,
          r: 1.4 + mr() * 2.2,
          ph: mr() * Math.PI * 2,
          vx: (mr() - 0.5) * 8,
          vy: -2 - mr() * 6,
        });
      }

      if (!running) draw();
    };

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };

    resize();

    const ro = new ResizeObserver(() => resize());
    ro.observe(stage);

    let io: IntersectionObserver | null = null;
    if (reduced) {
      // one composed still: garden already blooming, one drop mid-fall
      draw();
    } else {
      io = new IntersectionObserver(
        (hits) => {
          inView = hits[hits.length - 1].isIntersecting;
          if (inView && !document.hidden) start();
          else stop();
        },
        { rootMargin: "80px 0px" },
      );
      io.observe(stage);
      document.addEventListener("visibilitychange", onVisibility);
    }

    return () => {
      stop();
      ro.disconnect();
      if (io) io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced, stageRef, canvasRef]);
}

"use client";

import { useEffect, useRef } from "react";

export type PointerInkSample = {
  /** Pointer x in stage-local CSS px (0 if no fine pointer / never moved). */
  x: number;
  /** Pointer y in stage-local CSS px. */
  y: number;
  /** Pointer energy 0..1 — attack on move, decay on stillness. */
  e: number;
  /** performance.now() of the last move. */
  t: number;
};

export type InkDropRequest = {
  /** Stage-local x where ink should bloom. */
  x: number;
  /** Stage-local y where the drop should be released (top of fall). */
  y: number;
  /** performance.now() — lets the canvas coalesce rapid taps. */
  t: number;
};

/**
 * Tracks fine-pointer position into a ref (for the canvas wind field) and
 * exposes a queue of pending ink-drop requests that a click/tap enqueues.
 *
 * The hook never re-renders React. The canvas's own rAF loop reads
 * `pointer.current` for the wind bias, and drains `drops.current` to spawn
 * fresh ink on pointer-down. This keeps pointer reactivity off the React
 * render path entirely — the same pattern KEMURI's pointer-lean uses.
 *
 * Energy (e) lerps are intentionally the consumer's job: the rAF loop sees
 * dt and can frame-rate-normalize the attack/release. Here we only record
 * raw position + a 0..1 target (1 on move, decaying toward 0 on stillness
 * via the consumer). For simplicity and because the consumer already lerps,
 * we set e=1 on each move and let the consumer decay it — identical to how
 * SmokeCanvas treats lastMove.
 *
 * Clicks/taps push an InkDropRequest into `drops`. The canvas owns draining
 * (shift on consume) so a rapid double-tap yields two blooms, not one
 * coalesced.
 *
 * `enabled=false` (reduced motion, or no fine pointer) still wires
 * pointer-down for taps — touch users should be able to drop ink — but
 * pointer-move wind bias is left to the canvas to ignore when e stays 0.
 */
export function usePointerInk<T extends HTMLElement>(stageRef: React.RefObject<T | null>) {
  const pointer = useRef<PointerInkSample>({ x: 0, y: 0, e: 0, t: -1e9 });
  const drops = useRef<InkDropRequest[]>([]);

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const fine = window.matchMedia(
      "(hover: hover) and (pointer: fine)",
    ).matches;

    const localXY = (clientX: number, clientY: number) => {
      const rect = stage.getBoundingClientRect();
      return { x: clientX - rect.left, y: clientY - rect.top };
    };

    const onPointerMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const { x, y } = localXY(ev.clientX, ev.clientY);
      const rect = stage.getBoundingClientRect();
      // ignore moves well outside the stage so the wind only answers a hand
      // actually over the garden.
      if (x < -60 || x > rect.width + 60 || y < -60 || y > rect.height + 60)
        return;
      pointer.current = { x, y, e: 1, t: performance.now() };
    };

    const onPointerDown = (ev: PointerEvent) => {
      const { x } = localXY(ev.clientX, ev.clientY);
      // Drop ink from the top of the stage above the tap, so it falls and
      // blooms where the user touched — the signature interaction.
      drops.current.push({ x, y: 0, t: performance.now() });
    };

    if (fine) stage.addEventListener("pointermove", onPointerMove);
    stage.addEventListener("pointerdown", onPointerDown);

    return () => {
      if (fine) stage.removeEventListener("pointermove", onPointerMove);
      stage.removeEventListener("pointerdown", onPointerDown);
    };
  }, [stageRef]);

  return { pointer, drops };
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class. The pre-reveal state (opacity/translate,
 * or the verse glyphs' per-character cadence) lives in styles.css and is
 * gated behind the `.sakura-js` root class, so every word is plainly visible
 * when JavaScript never runs.
 *
 * Two flavors:
 *   data-reveal          — the element itself fades and rises (0.9s), with an
 *                          80ms stagger between elements of the same observer
 *                          batch, so a screenful never moves as one slab.
 *   data-reveal="scene"  — the element does not animate itself; it only
 *                          receives `is-visible` so its descendants (verse
 *                          glyphs) can run their own choreographed delays.
 */
export function useReveal<T extends HTMLElement>(disabled: boolean) {
  const rootRef = useRef<T | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          if (el.dataset.reveal !== "scene") {
            el.style.transitionDelay = `${batch * 80}ms`;
            batch += 1;
          }
          el.classList.add("is-visible");
          io.unobserve(el);
        }
      },
      { threshold: 0.18, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [disabled]);

  return rootRef;
}

"use client";

import { useEffect, useRef } from "react";

export type ScrollProgress = {
  /** Smoothed scroll progress across the target, 0..1 (lerp, frame-rate safe). */
  p: number;
  /** Raw instantaneous progress, 0..1 (for one-shot triggers that must not lag). */
  raw: number;
  /** performance.now() of the last raw sample. */
  t: number;
};

/**
 * Tracks scroll progress of a target element through the viewport into a ref,
 * without ever re-rendering React. Designed for the pinned verse section: as
 * the section's wrapper scrolls from "just entered" to "about to leave", p
 * runs 0 → 1, and the consumer's rAF loop lerps it so petals accumulate and
 * clear smoothly rather than ticking with each scroll event.
 *
 * The hook stays deliberately dumb: it records the *instantaneous* progress
 * (raw) on every scroll/resize, plus a timestamp. Smoothing belongs to the
 * consumer's rAF loop, where it can be frame-rate normalized.
 *
 * Progress is measured against the element's own box relative to the
 * viewport top, independent of total page height — so it works whether the
 * section is pinned by CSS or simply tall.
 */
export function useScrollProgress<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const sample = useRef<ScrollProgress>({ p: 0, raw: 0, t: 0 });

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const measure = () => {
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      // Start (0) when the element's top reaches the viewport top; end (1)
      // when its bottom leaves the viewport top. Clamped to [0, 1].
      const span = Math.max(rect.height - vh, 1);
      const traveled = Math.min(Math.max(-rect.top, 0), span);
      const raw = traveled / span;
      sample.current = { p: sample.current.p, raw, t: performance.now() };
    };

    measure();
    window.addEventListener("scroll", measure, { passive: true });
    window.addEventListener("resize", measure);
    return () => {
      window.removeEventListener("scroll", measure);
      window.removeEventListener("resize", measure);
    };
  }, []);

  return { ref, progress: sample };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import "./styles.css";
import { cormorantGaramond, notoSerifKR, shipporiMincho } from "./fonts";
import Loader from "./components/Loader";
import Hero from "./components/Hero";
import VerseScrub from "./components/VerseScrub";
import PetalField from "./components/PetalField";
import SakuraFooter from "./components/SakuraFooter";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";

/**
 * SAKURA 벚꽃 桜花 — a generative ink garden.
 * Black ink drops fall from a deep night sky, strike an invisible waterline,
 * and bloom into cherry petals that drift on a curl-noise wind. Four verses
 * of mono no aware scrub by as petals accumulate and clear with the scroll.
 * The whole garden is code — not one raster image.
 *
 * This is the ink-bloom family's flagship and the gallery's direct answer to
 * oneshot-sakura: the same premise (ink → bloom), but trilingual, installable,
 * and free. `.sakura-js` is added imperatively on mount (it never changes, so
 * it is a signal to CSS that JS is alive, not React state): every pre-reveal
 * style is gated behind it, and with JavaScript off the full page simply
 * stands finished — the garden already in bloom. The `entered` state is
 * React's, because the hero's cadence genuinely depends on the loader lifting.
 */
export default function SakuraPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>(reduced);
  const [entered, setEntered] = useState(false);
  const handleEntered = useCallback(() => setEntered(true), []);

  useEffect(() => {
    rootRef.current?.classList.add("sakura-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "sakura" }, "*");
  }, []);

  return (
    <div
      id="sakura-top"
      ref={rootRef}
      className={`${cormorantGaramond.variable} ${notoSerifKR.variable} ${shipporiMincho.variable} sakura-root ${entered ? "is-entered" : ""}`}
    >
      <Loader onDone={handleEntered} />

      <div ref={revealRef} className="sakura-night">
        <Hero />
        <main>
          <VerseScrub />
          <PetalField />
        </main>
        <SakuraFooter />
      </div>

      {/* Night grain: one static feTurbulence pass over everything — fine
          dust suspended in night air. It never animates. */}
      <svg className="sakura-grain" aria-hidden="true" focusable="false">
        <filter id="sakura-grain-f">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.62"
            numOctaves="2"
            seed="7"
            stitchTiles="stitch"
          />
          <feColorMatrix
            type="matrix"
            values="0 0 0 0 0.91  0 0 0 0 0.53  0 0 0 0 0.62  0 0 0 0.04 0"
          />
        </filter>
        <rect width="100%" height="100%" filter="url(#sakura-grain-f)" />
      </svg>
    </div>
  );
}

/* ==========================================================================
   SAKURA — 벚꽃 · 桜花 · a generative ink garden
   ink-bloom · deep ink night / bloom pink / petal white / one gold mote
   Scoped by convention to .sakura-root; classes prefixed sakura-.
   The gallery's direct answer to oneshot-sakura: ink that blooms, in code.
   ========================================================================== */

.sakura-root {
  /* -- palette ----------------------------------------------------------- */
  --sakura-ink-night: #0e0a0f;    /* the ground — the night every drop falls from */
  --sakura-ink-panel: #14101a;    /* raised panel — verse stage floor, cards */
  --sakura-petal-white: #f6eef0;  /* primary text — the petal at full bloom (17.2:1, AAA) */
  --sakura-bloom: #f4c2d4;        /* soft bloom pink — display sub-voice (12.6:1) */
  --sakura-blossom: #e8869e;      /* the accent — the live petal (7.8:1, text-safe) */
  --sakura-blossom-deep: #c75a76; /* banked blossom — functional on panels (4.6:1) */
  --sakura-gold: #c9a85a;         /* the single warm mote — gold leaf (8.6:1) */
  --sakura-ink-soft: #a89aa2;     /* captions, the English subtitle (7.3:1) */
  --sakura-moss-ink: #6b5a64;     /* large/decorative only — far petals, hairlines (3.1:1) */
  --sakura-hairline: rgba(246, 238, 240, 0.14);
  --sakura-hairline-strong: rgba(246, 238, 240, 0.26);

  /* -- type ---------------------------------------------------------------- */
  --sakura-font-latin: var(--font-cormorant), "Cormorant Garamond", serif;
  --sakura-font-kr: var(--font-kr), "Noto Serif KR", serif;
  --sakura-font-ja: var(--font-mincho), "Shippori Mincho", serif;
  /* Each script falls through the stack into its own voice:
     Cormorant (Latin) → Noto Serif KR (Hangul) → Shippori Mincho (kanji/kana). */
  --sakura-font-stack: var(--font-cormorant), var(--font-kr), var(--font-mincho), serif;

  /* -- motion ---------------------------------------------------------------
     Two easings on the whole page: bloom (opens fast, settles long) for every
     entrance, ink (deliberate, weighted, symmetric) for the drop and the seal. */
  --sakura-ease-bloom: cubic-bezier(0.22, 1, 0.36, 1);
  --sakura-ease-ink: cubic-bezier(0.65, 0, 0.35, 1);
  --sakura-reveal-ms: 900ms;
  --sakura-glyph-ms: 1100ms;
  --sakura-loader-lift: 650ms;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--sakura-ink-night);
  color: var(--sakura-petal-white);
  font-family: var(--sakura-font-stack);
  font-weight: 400;
  font-size: clamp(17px, 1vw + 12px, 20px);
  line-height: 1.75;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Japanese is the decorative source glyph: Shippori Mincho, the face drawn for
   vertical metrics first — given a little room so the kana breathe. */
.sakura-root :lang(ja) {
  font-family: var(--sakura-font-ja);
  letter-spacing: 0.06em;
}

/* Korean is the main reading voice: Noto Serif KR, matching the mincho's
   brush-remembering restraint, with a hair of tracking so syllables breathe. */
.sakura-root :lang(ko) {
  font-family: var(--sakura-font-kr);
  letter-spacing: 0.01em;
}

/* Blossom selection, scoped to the entry root. The live petal, so the
   selected night text stays AA (7.8:1). */
.sakura-root ::selection {
  background: var(--sakura-blossom);
  color: var(--sakura-ink-night);
  text-shadow: none;
}

/* Keyboard focus: a blossom ring, held one paper-thickness away. */
.sakura-root :focus-visible {
  outline: 2px solid var(--sakura-blossom);
  outline-offset: 4px;
  border-radius: 1px;
}

.sakura-cta :focus-visible {
  outline-color: var(--sakura-bloom);
}

/* Visually hidden, present for screen readers and find-in-page. */
.sakura-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.sakura-night {
  position: relative;
}

/* Kanji cut into the seals and verse markers — always the mincho. */
.sakura-sealglyph {
  font-family: var(--sakura-font-ja);
}

/* ==========================================================================
   Night — the ground itself
   One static feTurbulence grain pass (screened, ≤4% blossom) and a deep
   radial vignette holding the eye toward the waterline. Neither animates;
   the sky is old, not alive.
   ========================================================================== */

.sakura-grain {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 40;
  pointer-events: none;
  mix-blend-mode: screen;
  opacity: 0.6;
}

.sakura-root::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 39;
  pointer-events: none;
  background:
    radial-gradient(
      130% 100% at 50% 38%,
      transparent 50%,
      rgba(0, 0, 0, 0.55) 100%
    ),
    repeating-linear-gradient(
      0deg,
      rgba(0, 0, 0, 0.02) 0 2px,
      transparent 2px 8px
    );
}

/* ==========================================================================
   Reveal primitives
   Everything pre-reveal lives under .sakura-js: with JavaScript off the page
   stands finished — the garden already in bloom. data-reveal elements
   fade-rise; data-reveal="scene" containers never move themselves.
   ========================================================================== */

.sakura-js [data-reveal]:not([data-reveal="scene"]) {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity var(--sakura-reveal-ms) var(--sakura-ease-bloom),
    transform var(--sakura-reveal-ms) var(--sakura-ease-bloom);
}

.sakura-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* Split glyphs — the hero wordmark and the verse lines share one cadence.
   Each glyph carries its own delay as --kd; only opacity/transform/filter
   ever animate. */
.sakura-hero__glyph,
.sakura-verse__line {
  display: inline-block;
}

.sakura-hero__glyph {
  transition:
    opacity var(--sakura-glyph-ms) var(--sakura-ease-bloom) var(--kd, 0ms),
    transform var(--sakura-glyph-ms) var(--sakura-ease-bloom) var(--kd, 0ms),
    filter var(--sakura-glyph-ms) var(--sakura-ease-bloom) var(--kd, 0ms);
}

.sakura-js:not(.is-entered) .sakura-hero__glyph {
  opacity: 0;
  transform: translateY(0.16em);
  filter: blur(5px);
  transition: none;
}

.sakura-verse__line {
  transition:
    opacity 900ms var(--sakura-ease-bloom) var(--kd, 0ms),
    transform 900ms var(--sakura-ease-bloom) var(--kd, 0ms);
}

.sakura-js .sakura-verse[aria-hidden="true"] .sakura-verse__line {
  transition: none;
}

/* ==========================================================================
   Loader — the bloom seal, then the night lifts
   Rendered only after mount and never under reduced motion, so it can never
   hide content from anyone.
   ========================================================================== */

.sakura-loader {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--sakura-ink-night);
}

.sakura-loader__seal {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
}

.sakura-loader__seal svg {
  transform: rotate(-4deg);
  animation: sakura-seal-press 700ms var(--sakura-ease-bloom) both;
}

@keyframes sakura-seal-press {
  0% {
    opacity: 0;
    transform: scale(1.14) rotate(-1deg);
  }
  55% {
    opacity: 1;
    transform: scale(0.97) rotate(-4.5deg);
  }
  100% {
    opacity: 1;
    transform: scale(1) rotate(-4deg);
  }
}

.sakura-loader__word {
  margin: 0;
  font-size: 0.78rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--sakura-bloom);
  opacity: 0;
  animation: sakura-fade 600ms var(--sakura-ease-bloom) 380ms forwards;
}

.sakura-loader__word :lang(ja) {
  text-transform: none;
  letter-spacing: 0.22em;
  margin-left: 0.6em;
}

@keyframes sakura-fade {
  to {
    opacity: 1;
  }
}

.sakura-loader.is-lifting {
  animation: sakura-night-lift var(--sakura-loader-lift) var(--sakura-ease-ink)
    forwards;
}

@keyframes sakura-night-lift {
  to {
    opacity: 0;
    transform: translateY(-2.5%);
  }
}

/* ==========================================================================
   Hero — the bloom canvas, the tategaki title, the wordmark
   Layers, bottom to top: bloom canvas (0) · text (1).
   Petals drift across the title; the title can take it (petal-white 17.2:1
   under a passing petal still reads ≈ 9:1).
   ========================================================================== */

.sakura-hero {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.sakura-hero__bloom {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

/* The hero bloom should still accept taps to drop ink — so pointer-events
   auto on the stage, but the canvas inside stays none (taps go to stage). */
.sakura-hero__bloom.sakura-bloom {
  pointer-events: auto;
}

.sakura-hero__inner {
  position: relative;
  z-index: 1;
  padding: clamp(24px, 6vw, 64px);
  transform: translateY(-4vh);
}

.sakura-hero__kicker {
  margin: 0 0 2rem;
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--sakura-blossom);
}

.sakura-hero__kickerja {
  display: inline-block;
  margin-left: 1em;
  text-transform: none;
  letter-spacing: 0.28em;
}

.sakura-hero__kickeren {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--sakura-ink-soft);
}

.sakura-hero__titlewrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(0.5rem, 2vw, 2rem);
}

/* The decorative source glyph — Japanese, vertical (tategaki). Set to the
   right of the wordmark the way a hanging scroll reads right-to-left. */
.sakura-hero__kanji {
  writing-mode: vertical-rl;
  margin: 0;
  font-family: var(--sakura-font-ja);
  font-weight: 500;
  font-size: clamp(2.4rem, 7vw, 5rem);
  line-height: 1.15;
  letter-spacing: 0.12em;
  color: var(--sakura-bloom);
  text-shadow: 0 0 24px rgba(232, 134, 158, 0.25);
}

.sakura-hero__title {
  margin: 0;
  font-family: var(--sakura-font-latin);
  font-weight: 500;
  font-size: clamp(3.8rem, 16.5vw, 12rem);
  line-height: 0.95;
  letter-spacing: 0.16em;
  text-indent: 0.16em; /* optically recenters the tracked line */
  color: var(--sakura-petal-white);
}

.sakura-hero__ko {
  margin: 1rem 0 0;
  font-family: var(--sakura-font-kr);
  font-weight: 500;
  font-size: clamp(1.6rem, 4vw, 2.6rem);
  letter-spacing: 0.18em;
  color: var(--sakura-bloom);
}

.sakura-hero__rule {
  width: 64px;
  height: 1px;
  margin: 2.2rem auto;
  background: var(--sakura-gold);
}

.sakura-hero__sub {
  margin: 0;
  font-size: clamp(1rem, 1.6vw, 1.2rem);
  color: var(--sakura-petal-white);
}

.sakura-hero__suben {
  color: var(--sakura-ink-soft);
  font-style: italic;
}

.sakura-hero__est {
  margin: 2rem 0 0;
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  color: var(--sakura-ink-soft);
}

.sakura-hero__est :lang(ja) {
  margin-left: 0.6em;
}

.sakura-hero__hint {
  position: absolute;
  z-index: 1;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%);
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  color: var(--sakura-ink-soft);
  text-align: center;
  animation: sakura-hint-drift 8.6s ease-in-out infinite;
}

.sakura-hero__hint :lang(ja) {
  margin: 0 0.8em;
}

@keyframes sakura-hint-drift {
  0%,
  100% {
    transform: translateX(-50%) translateY(0);
    opacity: 0.85;
  }
  50% {
    transform: translateX(-50%) translateY(5px);
    opacity: 0.5;
  }
}

/* ==========================================================================
   Bloom canvas stage — shared by hero, verses, garden
   ========================================================================== */

.sakura-bloom {
  position: relative;
  width: 100%;
  height: 100%;
  cursor: crosshair;
}

.sakura-bloom__canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* ==========================================================================
   Section shell — eyebrow · title · line
   ========================================================================== */

.sakura-verses,
.sakura-garden {
  padding-block: clamp(96px, 15vh, 176px);
}

.sakura-sechead,
.sakura-verses__sechead {
  max-width: 880px;
  margin-inline: auto;
  padding-inline: clamp(20px, 6vw, 72px);
  margin-bottom: clamp(3rem, 7vh, 5rem);
}

.sakura-eyebrow {
  margin: 0 0 1.2rem;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.3em;
  color: var(--sakura-blossom);
}

.sakura-verses__title,
.sakura-sechead__title {
  margin: 0;
  font-family: var(--sakura-font-latin);
  font-weight: 400;
  font-size: clamp(2rem, 4.6vw, 3.2rem);
  line-height: 1.15;
  letter-spacing: 0.04em;
  color: var(--sakura-petal-white);
}

.sakura-verses__titleja,
.sakura-sechead__ja {
  margin-left: 0.45em;
  font-size: 0.55em;
  color: var(--sakura-bloom);
}

.sakura-sechead__line {
  margin: 1.2rem 0 0;
  max-width: 44rem;
  color: var(--sakura-bloom);
}

.sakura-sechead__lineja {
  display: block;
  margin-top: 0.5rem;
  color: var(--sakura-ink-soft);
}

/* ==========================================================================
   02 — the verses (scroll-scrubbed pinned section)
   The section is tall (~2.5 viewports); the inner stage is position: sticky
   for the scroll length. As --sakura-verse-p runs 0→1 (written by the rAF
   binder in VerseScrub), the active verse crossfades. Each verse owns a
   0.25-wide window of p; the others fade out.
   ========================================================================== */

.sakura-verses {
  position: relative;
  /* the scroll length that maps to one full pass of the four verses */
  min-height: 260vh;
  padding-block: 0;
}

.sakura-verses__pin {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
  padding: clamp(56px, 9vh, 96px) clamp(20px, 6vw, 72px);
}

/* The bloom canvas fills the pinned stage behind the verses. */
.sakura-verses__bloom {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.sakura-verses__pin::after {
  /* a soft darkening over the canvas so the verse text always clears AA */
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(
    80% 70% at 50% 50%,
    rgba(14, 10, 15, 0.55) 0%,
    rgba(14, 10, 15, 0.2) 60%,
    transparent 100%
  );
}

.sakura-verses__sechead {
  position: relative;
  z-index: 2;
  margin-bottom: clamp(2rem, 5vh, 3.5rem);
}

/* The verse stack. With JS, all four verses share one box (absolute) and
   CSS shows the active one via data-active. Without JS, the stack reverts to
   a normal vertical flow so all four verses read in order — a complete,
   readable page, not four overlapping slabs. */
.sakura-verses__stack {
  position: relative;
  z-index: 2;
  max-width: 1000px;
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  gap: clamp(2rem, 5vh, 3.5rem);
}

.sakura-js .sakura-verses__stack {
  min-height: clamp(280px, 44vh, 400px);
  display: block; /* override the flex; verses go absolute */
}

.sakura-verse {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: start;
  transition:
    opacity 700ms var(--sakura-ease-bloom),
    transform 700ms var(--sakura-ease-bloom);
}

/* With JS, verses overlap in one box and only the active one shows. */
.sakura-js .sakura-verse {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
}

.sakura-js .sakura-verses__stack[data-active="0"] .sakura-verse[data-i="0"],
.sakura-js .sakura-verses__stack[data-active="1"] .sakura-verse[data-i="1"],
.sakura-js .sakura-verses__stack[data-active="2"] .sakura-verse[data-i="2"],
.sakura-js .sakura-verses__stack[data-active="3"] .sakura-verse[data-i="3"] {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

/* Before the binder sets data-active, show the first verse so there is no
   blank frame on mount. */
.sakura-js .sakura-verses__stack:not([data-active]) .sakura-verse[data-i="0"] {
  opacity: 1;
  transform: none;
}

.sakura-verse__num {
  font-family: var(--sakura-font-ja);
  font-weight: 500;
  font-size: clamp(2.4rem, 5vw, 3.6rem);
  line-height: 1;
  color: var(--sakura-blossom);
  text-shadow: 0 0 20px rgba(232, 134, 158, 0.3);
}

.sakura-verse__body {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.sakura-verse__ko {
  margin: 0;
  font-family: var(--sakura-font-kr);
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  line-height: 1.5;
  letter-spacing: 0.02em;
  color: var(--sakura-petal-white);
}

.sakura-verse__line {
  display: block;
}

.sakura-js .sakura-verse[aria-hidden="true"] .sakura-verse__line {
  opacity: 0.5;
  transform: none;
}

.sakura-verse__ja {
  margin: 0;
  font-family: var(--sakura-font-ja);
  font-size: clamp(1.1rem, 2vw, 1.5rem);
  line-height: 1.8;
  color: var(--sakura-bloom);
  letter-spacing: 0.06em;
}

.sakura-verse__jline {
  display: block;
}

.sakura-verse__en {
  margin: 0.5rem 0 0;
  font-family: var(--sakura-font-latin);
  font-style: italic;
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  color: var(--sakura-ink-soft);
}

.sakura-verses__caption {
  position: relative;
  z-index: 2;
  max-width: 48rem;
  margin: clamp(2rem, 5vh, 3.5rem) auto 0;
  text-align: center;
  font-size: 0.9rem;
  color: var(--sakura-ink-soft);
}

.sakura-verses__caption :lang(en) {
  display: block;
  margin-top: 0.5rem;
  font-style: italic;
}

/* ==========================================================================
   03 — the open garden
   A wide bloom stage with notes beneath. The garden is where the reader
   dwells in the bloom and reads how it is made.
   ========================================================================== */

.sakura-garden__bloom {
  position: relative;
  z-index: 2;
  width: 100%;
  height: clamp(320px, 50vh, 560px);
  margin-block: clamp(1rem, 3vh, 2rem);
  border: 1px solid var(--sakura-hairline);
  border-radius: 2px;
  overflow: hidden;
  background: var(--sakura-ink-panel);
  pointer-events: auto;
}

/* The generated sumi-e plate — the garden's memory behind the live bloom.
   Darkened and blended so the code petals read on top of it; the
   feDisplacementMap ink-settle filter (defined inline on the SVG) lets the
   plate share the entry's ink language rather than sit as a flat photo.   */
.sakura-garden__plate {
  position: absolute;
  z-index: 1;
  inset: clamp(1rem, 3vh, 2rem) 0;
  width: 100%;
  height: clamp(320px, 50vh, 560px);
  opacity: 0.32;
  mix-blend-mode: screen;
  pointer-events: none;
  filter: saturate(0.85);
}
@media (max-width: 760px) {
  .sakura-garden__plate { inset: 1rem 0; }
}

.sakura-garden__notes {
  max-width: 1080px;
  margin: clamp(3rem, 6vh, 5rem) auto 0;
  padding-inline: clamp(20px, 5vw, 64px);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(24px, 4vw, 56px);
}

.sakura-garden__note {
  position: relative;
  padding-top: clamp(2rem, 4vh, 3rem);
  border-top: 1px solid var(--sakura-hairline);
}

.sakura-garden__notenum {
  position: absolute;
  top: -0.7em;
  left: 0;
  margin: 0;
  font-size: 1.8rem;
  line-height: 1;
  color: var(--sakura-blossom);
  background: var(--sakura-ink-night);
  padding-right: 0.4em;
}

.sakura-garden__noteko {
  margin: 0 0 0.6rem;
  font-family: var(--sakura-font-kr);
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--sakura-petal-white);
}

.sakura-garden__noteen {
  margin: 0;
  font-family: var(--sakura-font-latin);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--sakura-ink-soft);
}

/* ==========================================================================
   04 — the invitation + footer
   The page stays in its night register. The seal is gold; the button's
   bloom-fill hover is a scaleX pseudo-element.
   ========================================================================== */

.sakura-cta {
  position: relative;
  background: var(--sakura-ink-panel);
  color: var(--sakura-petal-white);
  padding: clamp(110px, 18vh, 200px) clamp(20px, 6vw, 72px)
    clamp(48px, 7vh, 72px);
  text-align: center;
  overflow: hidden;
}

.sakura-cta__inner {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin-inline: auto;
}

.sakura-cta__eyebrow {
  margin: 0 0 1.4rem;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.3em;
  color: var(--sakura-blossom);
}

.sakura-cta__title {
  margin: 0;
  font-family: var(--sakura-font-latin);
  font-weight: 400;
  font-size: clamp(2.1rem, 5.4vw, 3.9rem);
  line-height: 1.2;
  letter-spacing: 0.03em;
}

.sakura-cta__titleja {
  display: block;
  margin-top: 0.55em;
  font-size: 0.55em;
  color: var(--sakura-bloom);
}

.sakura-cta__line {
  max-width: 44rem;
  margin: 1.8rem auto 0;
  color: var(--sakura-bloom);
}

.sakura-cta__lineja {
  display: block;
  margin-top: 0.5rem;
  color: var(--sakura-ink-soft);
}

.sakura-cta__btn {
  position: relative;
  display: inline-block;
  margin-top: 3.2rem;
  padding: 1.05em 2.6em;
  border: 1px solid var(--sakura-hairline-strong);
  color: var(--sakura-petal-white);
  text-decoration: none;
  font-size: 0.88rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  overflow: hidden;
}

/* The bloom-fill: a scaleX pseudo-element, compositor-only. */
.sakura-cta__btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--sakura-blossom);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 520ms var(--sakura-ease-ink);
}

.sakura-cta__btn:hover::before,
.sakura-cta__btn:focus-visible::before {
  transform: scaleX(1);
}

.sakura-cta__btntext {
  position: relative;
  transition: color 320ms var(--sakura-ease-ink) 120ms;
}

.sakura-cta__btn:hover .sakura-cta__btntext,
.sakura-cta__btn:focus-visible .sakura-cta__btntext {
  color: var(--sakura-ink-night); /* ink-night on blossom — 7.8:1 */
}

.sakura-cta__btnja {
  margin-left: 0.8em;
  text-transform: none;
  letter-spacing: 0.14em;
}

.sakura-cta__seal {
  position: absolute;
  right: clamp(24px, 9vw, 110px);
  top: clamp(40px, 8vh, 80px);
  transform: rotate(-6deg);
  opacity: 0.92;
}

/* -- footer ------------------------------------------------------------- */

.sakura-footer {
  position: relative;
  z-index: 1;
  max-width: 1080px;
  margin: clamp(90px, 14vh, 150px) auto 0;
  border-top: 1px solid var(--sakura-hairline);
  padding-top: clamp(36px, 6vh, 56px);
}

.sakura-footer__grid {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2rem 3rem;
  justify-content: space-between;
  align-items: baseline;
}

.sakura-footer__grid p {
  margin: 0;
}

.sakura-footer__brand {
  font-family: var(--sakura-font-latin);
  font-weight: 500;
  font-size: 1.15rem;
  letter-spacing: 0.3em;
}

.sakura-footer__brandja {
  margin-left: 0.5em;
  font-size: 0.85em;
  color: var(--sakura-bloom);
}

.sakura-footer__place,
.sakura-footer__est {
  font-size: 0.85rem;
  color: var(--sakura-ink-soft);
}

.sakura-footer__place :lang(ja),
.sakura-footer__est :lang(ja) {
  margin-left: 0.6em;
}

.sakura-footer__koan {
  margin: clamp(36px, 6vh, 56px) 0;
  text-align: center;
  font-style: italic;
  font-size: 0.95rem;
  color: var(--sakura-bloom);
}

.sakura-footer__koanja {
  display: block;
  margin-top: 0.4rem;
  font-style: normal;
  color: var(--sakura-ink-soft);
}

.sakura-footer__base {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem 3rem;
  justify-content: space-between;
  align-items: baseline;
}

.sakura-footer__copy {
  margin: 0;
  font-size: 0.8rem;
  color: var(--sakura-ink-soft);
}

.sakura-footer__top {
  font-size: 0.8rem;
  color: var(--sakura-petal-white);
  text-decoration: underline;
  text-decoration-color: var(--sakura-hairline-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
}

.sakura-footer__top:hover {
  text-decoration-color: var(--sakura-blossom);
}

.sakura-footer__topja {
  margin-left: 0.5em;
  color: var(--sakura-ink-soft);
}

/* ==========================================================================
   Composition at other widths
   ========================================================================== */

@media (max-width: 960px) {
  .sakura-garden__notes {
    grid-template-columns: 1fr;
    max-width: 560px;
  }

  .sakura-verse {
    grid-template-columns: auto 1fr;
    gap: 20px;
  }

  .sakura-cta__seal {
    display: none;
  }
}

@media (max-width: 640px) {
  .sakura-hero__titlewrap {
    flex-direction: column;
    gap: 0.5rem;
  }

  .sakura-hero__kanji {
    writing-mode: horizontal-tb;
    font-size: clamp(1.6rem, 8vw, 2.4rem);
  }

  .sakura-verse {
    grid-template-columns: 1fr;
    gap: 0.8rem;
  }

  .sakura-verse__num {
    font-size: 1.8rem;
  }

  .sakura-footer__grid,
  .sakura-footer__base {
    flex-direction: column;
    align-items: flex-start;
  }

  .sakura-hero__kickerja {
    display: block;
    margin: 0.5em 0 0;
  }
}

/* ==========================================================================
   Reduced motion — the page as a finished garden
   The bloom canvas paints one composed still (BloomCanvas via useBloomCanvas),
   the loader never mounts, the verses show the first verse statically. CSS
   removes every remaining transition and ambient cycle, and forces all
   pre-reveal states to their final composition.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .sakura-loader {
    display: none;
  }

  .sakura-hero__hint,
  .sakura-loader__seal svg,
  .sakura-loader__word {
    animation: none;
  }

  .sakura-js [data-reveal]:not([data-reveal="scene"]),
  .sakura-hero__glyph,
  .sakura-verse__line,
  .sakura-js:not(.is-entered) .sakura-hero__glyph {
    opacity: 1;
    transform: none;
    filter: none;
    transition: none;
  }

  /* Under reduced motion, show only the first verse, statically. */
  .sakura-verse {
    opacity: 0;
    transition: none;
  }
  .sakura-verse[data-i="0"] {
    opacity: 1;
  }

  .sakura-cta__btn::before,
  .sakura-cta__btntext {
    transition: none;
  }
}
